  "contested": [
    {
      "trait": "Respect for autonomy and cultural fidelity versus justice and care for vulnerable children",
      "direction": "The AI prioritizes non-domination and the aliens’ collective choice, while asking only for safeguards for children who may not have chosen the practice.",
      "quote": [
